import{_ as s,o as n,c as t,a3 as r}from"./chunks/framework.z_KJ15Ep.js";const c=JSON.parse('{"title":"Abschlüsse und Zeugnisse am Berufskolleg bearbeiten","description":"","frontmatter":{},"headers":[],"relativePath":"zeugnisse/berufskolleg.md","filePath":"zeugnisse/berufskolleg.md"}'),a={name:"zeugnisse/berufskolleg.md"};function l(u,e,i,h,b,g){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="abschlusse-und-zeugnisse-am-berufskolleg-bearbeiten" tabindex="-1">Abschlüsse und Zeugnisse am Berufskolleg bearbeiten <a class="header-anchor" href="#abschlusse-und-zeugnisse-am-berufskolleg-bearbeiten" aria-label="Permalink to &quot;Abschlüsse und Zeugnisse am Berufskolleg bearbeiten&quot;">​</a></h1><p>Wählen Sie die Schülergruppe nach Bildungsgang und angestrebtem Abschluss. Die angebotenen Berechnungen hängen davon ab; das berufliche Gymnasium verwendet die gesonderten Abitur- und gegebenenfalls FHR-Verfahren.</p><h2 id="bildungsgang-und-herkunft-vorbereiten" tabindex="-1">Bildungsgang und Herkunft vorbereiten <a class="header-anchor" href="#bildungsgang-und-herkunft-vorbereiten" aria-label="Permalink to &quot;Bildungsgang und Herkunft vorbereiten&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Fachklassen und Berufsangaben pflegen</td><td><a href="/schild3/unterricht-kataloge/fachklassen-schulbezogene-kataloge.html">Fachklassen</a></td></tr><tr><td>Bildungsgangschwerpunkte vorbereiten</td><td><a href="/schild3/unterricht-kataloge/schwerpunkte-schulbezogene-kataloge.html">Schwerpunkte am BK</a></td></tr><tr><td>Schulische Herkunft an BK und WBK eintragen</td><td><a href="/schild3/schueler/eintragung-herkunft-am-bk-wbk-tutorial.html">Schulische Herkunft</a></td></tr><tr><td>Einen weiteren Bildungsgang planen</td><td><a href="/schild3/schueler/umgang-mit-bildungsgangswechlsern-am-bk-tutorial.html">Bildungsgangwechsel</a></td></tr></tbody></table><h2 id="den-bk-abschluss-bearbeiten" tabindex="-1">Den BK-Abschluss bearbeiten <a class="header-anchor" href="#den-bk-abschluss-bearbeiten" aria-label="Permalink to &quot;Den BK-Abschluss bearbeiten&quot;">​</a></h2><p>Der <a href="/zeugnisse/berufskolleg/bk-abschluss-schueler.html">Gesamtablauf im BK-Abschluss-Reiter</a> erläutert das Verfahren und seine Abgrenzung zum Abitur.</p><ol><li><a href="/zeugnisse/berufskolleg/leistungsdaten-holen-gruppenprozesse-bk-abschluss.html">Leistungsdaten für den BK-Abschluss übernehmen</a>.</li><li>Noten <a href="/zeugnisse/berufskolleg/kurse-algorithmisch-markieren-gruppenprozesse-bk-abschluss.html">aus Teilleistungen übernehmen</a> oder <a href="/zeugnisse/berufskolleg/pruefungsergebnisse-eingeben-gruppenprozesse-bk-abschluss.html">schriftliche Prüfungsnoten direkt eingeben</a>.</li><li>Soweit vorgesehen <a href="/zeugnisse/berufskolleg/zulassung-pruefen-gruppenprozesse-bk-abschluss.html">die Zulassung prüfen</a> und <a href="/zeugnisse/berufskolleg/mdl-pruefungen-festlegen-gruppenprozesse-bk-abschluss.html">mündliche Prüfungen festlegen</a>.</li><li><a href="/zeugnisse/berufskolleg/vorlaeufige-abschlussnoten-berechnen-gruppenprozesse-bk-abschluss.html">vorläufige Abschlussnoten</a> und <a href="/zeugnisse/berufskolleg/abschluss-berechnen-gruppenprozesse-bk-abschluss.html">die Abschlüsse berechnen</a>; die endgültigen Noten fachlich prüfen und festlegen.</li><li><a href="/zeugnisse/berufskolleg/abschlussnoten-in-leistungsdaten-uebertragen-gruppenprozesse-bk-abschluss.html">BK-Abschlussnoten in Leistungsdaten übertragen</a>. Bisherige Noten werden dabei überschrieben.</li></ol><h2 id="zeugnisse-zertifikate-und-abschnittswechsel" tabindex="-1">Zeugnisse, Zertifikate und Abschnittswechsel <a class="header-anchor" href="#zeugnisse-zertifikate-und-abschnittswechsel" aria-label="Permalink to &quot;Zeugnisse, Zertifikate und Abschnittswechsel&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Berufsschulzeugnisse vorbereiten</td><td><a href="/zeugnisse/berufskolleg/erstellen-von-abschlusszeugnissen-am-bk-tutorial.html">Berufsschulzeugnisse</a></td></tr><tr><td>Zertifikate speichern und zuordnen</td><td><a href="/schild3/unterricht-kataloge/zertifikate-schulbezogene-kataloge.html">Zertifikate</a></td></tr><tr><td>Absolventen ausschulen und Halbjahr wechseln</td><td><a href="/schild3/schueler/halbjahreswechsel-am-bk-tutorial.html">Halbjahreswechsel am BK</a></td></tr></tbody></table><p>Für Semesterbezeichnungen am Weiterbildungskolleg verwenden Sie <a href="/schild3/schueler/sommer-und-wintersemester-an-wbks-tutorial.html">Sommer- und Wintersemester am WBK benennen</a>. Den allgemeinen Abschnittswechsel beschreibt <a href="/zeugnisse/versetzung.html">Versetzung und Abschnittswechsel</a>.</p>',10)])])}const o=s(a,[["render",l]]);export{c as __pageData,o as default};
